--
-- Name: predict_home_win_prob(integer, integer); Type: FUNCTION; Schema: public; Owner: mlb
--

CREATE FUNCTION public.predict_home_win_prob(inning integer, home_score_diff integer) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
    DECLARE
        logit FLOAT;
    BEGIN
        -- Logit Equation generated from Python Scikit-Learn
        logit := 0.13372018954110457 + (0.027800166189916594 * inning) + (8.453407323736172 * home_score_diff);
        
        -- Sigmoid Activation
        RETURN 1.0 / (1.0 + exp(-logit));
    END;
    $$;


ALTER FUNCTION public.predict_home_win_prob(inning integer, home_score_diff integer) OWNER TO mlb;

--
-- Name: simulate_half_innings(integer); Type: FUNCTION; Schema: public; Owner: mlb
--

CREATE FUNCTION public.simulate_half_innings(num_simulations integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    sim INT;
    outs INT;
    runs INT;
    pa INT;
    bases INT[]; -- [1st, 2nd, 3rd] where 1 is occupied, 0 is empty
    rand FLOAT;
    event_outcome VARCHAR;
BEGIN
    FOR sim IN 1..num_simulations LOOP
        outs := 0;
        runs := 0;
        pa := 0;
        bases := ARRAY[0, 0, 0];
        
        WHILE outs < 3 LOOP
            pa := pa + 1;
            rand := random();
            
            -- Extremely simplified outcome generator based on global MLB averages 
            -- (Normally we'd SELECT this from gold.mart_woba_weights)
            IF rand < 0.22 THEN 
                event_outcome := 'strikeout';
            ELSIF rand < 0.31 THEN 
                event_outcome := 'single';
            ELSIF rand < 0.36 THEN 
                event_outcome := 'double';
            ELSIF rand < 0.365 THEN 
                event_outcome := 'triple';
            ELSIF rand < 0.395 THEN 
                event_outcome := 'home_run';
            ELSIF rand < 0.485 THEN 
                event_outcome := 'walk';
            ELSE 
                event_outcome := 'out';
            END IF;

            -- Advance runners based on outcome
            IF event_outcome = 'out' OR event_outcome = 'strikeout' THEN
                outs := outs + 1;
            ELSIF event_outcome = 'home_run' THEN
                runs := runs + 1 + bases[1] + bases[2] + bases[3];
                bases := ARRAY[0, 0, 0];
            ELSIF event_outcome = 'single' OR event_outcome = 'walk' THEN
                runs := runs + bases[3];
                bases[3] := bases[2];
                bases[2] := bases[1];
                bases[1] := 1;
            ELSIF event_outcome = 'double' THEN
                runs := runs + bases[3] + bases[2];
                bases[3] := bases[1];
                bases[2] := 1;
                bases[1] := 0;
            ELSIF event_outcome = 'triple' THEN
                runs := runs + bases[3] + bases[2] + bases[1];
                bases := ARRAY[0, 0, 1];
            END IF;
            
        END LOOP;
        
        -- Save simulation result
        INSERT INTO simulations.monte_carlo_inning_results (runs_scored, plate_appearances)
        VALUES (runs, pa);
        
    END LOOP;
END;
$$;


ALTER FUNCTION public.simulate_half_innings(num_simulations integer) OWNER TO mlb;

